using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Authorization;using RaceDay.Api.Data;using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api")]
public class RaceOperationsController(RaceDayDbContext db):ControllerBase {
 [Authorize(Roles="Organiser,Admin"),HttpPost("categories")] public async Task<IActionResult> Category(CategoryRequest r){if(!await db.Events.AnyAsync(x=>x.Id==r.EventId))return NotFound("Event not found.");var c=new RaceCategory{EventId=r.EventId,Name=r.Name,Description=r.Description};db.Categories.Add(c);await db.SaveChangesAsync();return Ok(c);}
 [Authorize(Roles="Participant"),HttpPost("enrollments")] public async Task<IActionResult> Enroll(EnrollRequest r){var pid=User.Identity?.Name??"";var category=await db.Categories.FirstOrDefaultAsync(x=>x.Id==r.CategoryId&&x.EventId==r.EventId);if(category is null)return BadRequest("Choose a category belonging to this event.");if(await db.Enrollments.AnyAsync(x=>x.EventId==r.EventId&&x.ParticipantId==pid))return Conflict("You are already enrolled.");var e=await db.Events.FindAsync(r.EventId);if(e is null||e.Date<DateTime.UtcNow)return BadRequest("This event is not available for enrolment.");var item=new RaceEnrollment{EventId=r.EventId,CategoryId=r.CategoryId,ParticipantId=pid};db.Enrollments.Add(item);await db.SaveChangesAsync();return Ok(item);}
 [Authorize(Roles="Organiser,Admin"),HttpGet("events/{eventId:int}/enrollments")] public async Task<IActionResult> Enrollments(int eventId)=>Ok(await db.Enrollments.Include(x=>x.Category).Where(x=>x.EventId==eventId).ToListAsync());
 [Authorize(Roles="Organiser,Admin"),HttpPost("results")] public async Task<IActionResult> Result(ResultRequest r){if(await db.Results.AnyAsync(x=>x.EnrollmentId==r.EnrollmentId))return Conflict("A result already exists.");var enrollment=await db.Enrollments.FindAsync(r.EnrollmentId);if(enrollment is null)return NotFound();var result=new RaceResult{EnrollmentId=r.EnrollmentId,FinishTime=r.FinishTime,Position=r.Position};db.Results.Add(result);await db.SaveChangesAsync();return Ok(result);}
 [Authorize(Roles="Participant"),HttpGet("participants/me/results")] public async Task<IActionResult> MyResults(){var id=User.Identity?.Name??"";return Ok(await db.Results.Include(x=>x.Enrollment)!.ThenInclude(x=>x!.Event).Include(x=>x.Enrollment)!.ThenInclude(x=>x!.Category).Where(x=>x.Enrollment!.ParticipantId==id).ToListAsync());}
}
